/* @lc app=leetcode id=3531 lang=kotlin */ class Solution { fun countCoveredBuildings(n: Int, buildings: Array<IntArray>): Int = buildings.groupBy({ it[1] }, { it[0] }).mapValues { (_, l) -> l.min() to l.max() }.let { rows -> buildings.groupBy({ it[0] }, { it[1] }).mapValues { (_, l) -> l.min() to l.max() }.let { cols -> buildings.count { (x, y) -> rows[y]!!.let { r -> r.first < x && x < r.second } && cols[x]!!.let { c -> c.first < y && y < c.second } } } } }